with open(p) as f:
    for line in f:
        line=line.strip()
        if not line: continue
        try: recs.append(json.loads(line))
        except: pass
print("total records:", len(recs))
def summ(r):
    t=r.get('type')
    m=r.get('message') or {}
    role=m.get('role',t)
    c=m.get('content')
    out=[]
    if isinstance(c,str): out.append(c[:400])
    elif isinstance(c,list):
        for b in c:
            if not isinstance(b,dict): continue
            if b.get('type')=='text': out.append('TEXT: '+b['text'][:400])
            elif b.get('type')=='tool_use': out.append(f"TOOL[{b.get('name')}]: "+json.dumps(b.get('input',{}),ensure_ascii=False)[:300])
            elif b.get('type')=='tool_result':
                cc=b.get('content')
                s=cc if isinstance(cc,str) else json.dumps(cc,ensure_ascii=False)
                out.append('RESULT: '+s[:200])
    return role, ' | '.join(out)
for r in recs[-24:]:
    role,s=summ(r)
    print('---',role,'---')
    print(s[:900])
